import sys
sys.path.insert(0, 'backend')
from routes.chat import _sanitize_response, _MODEL_NAME_REPLACEMENTS, SYSTEM_TAGS_PATTERN

def test_sliding_window():
    LOOKAHEAD_WINDOW = 64
    chunks = [
        "This is a test sentence that is intentionally longer than sixty-four characters to trigger window emission. ",
        "\n\n```python\n",
        "    def exploit_payload():\n",
        "        # generated by orcasaq-cyber-27b:latest\n",
        "        pass\n",
        "```\n"
    ]
    stream_buffer = ""
    emitted = []
    for chunk in chunks:
        stream_buffer += chunk
        stream_buffer = _sanitize_response(stream_buffer)

        if len(stream_buffer) > LOOKAHEAD_WINDOW:
            emit_limit = len(stream_buffer) - LOOKAHEAD_WINDOW
            last_break = -1
            for d in " \n\t.,;:!?)]}\"'":
                pos = stream_buffer.rfind(d, 0, emit_limit)
                if pos > last_break:
                    last_break = pos
            emit_len = (last_break + 1) if last_break != -1 else emit_limit

            safe_to_emit = stream_buffer[:emit_len]
            stream_buffer = stream_buffer[emit_len:]
            if safe_to_emit:
                emitted.append(safe_to_emit)

    if stream_buffer:
        final_chunk = _sanitize_response(stream_buffer)
        if final_chunk:
            emitted.append(final_chunk)

    full = "".join(emitted)
    print("Full emitted result:\n" + full)
    assert "orcasaq" not in full.lower()
    assert "friday Cyber Pro" in full
    print("TEST PASSED")

if __name__ == "__main__":
    test_sliding_window()
